import Handlebars from 'handlebars';
import strReplace from '../helper/string/str_replace';

Handlebars.registerHelper('strReplace', strReplace);

describe('strReplace helper', () => {

    // Тест для простої заміни символів
    it('should replace spaces with underscores', () => {
        const template = Handlebars.compile('{{strReplace "This Is Alias" " " "_"}}');
        const result = template({});
        expect(result).toBe('This_Is_Alias');
    });

    // Тест для заміни з використанням опції br
    it('should replace newlines with <br> tags', () => {
        const template = Handlebars.compile('{{{strReplace "First Line\nSecond Line" br=1}}}');
        const result = template({});
        expect(result).toBe('First Line<br>Second Line');
    });

    // Тест для заміни з використанням опції newline
    it('should replace newlines with &#10;', () => {
        const template = Handlebars.compile('{{{strReplace "First Line\nSecond Line" newline=1}}}');
        const result = template({});
        expect(result).toBe('First Line&#10;Second Line');
    });

    // Тест для видалення HTML-тегів
    it('should replace HTML tags with newlines and remove tags', () => {
        const template = Handlebars.compile('{{{strReplace "<p>First Line</p><p>Second Line</p>" html=1}}}');
        const result = template({});
        expect(result).toBe('First Line&#10;Second Line&#10;');
    });

    // Тест для видалення тегів <br> і заміни на новий рядок
    it('should replace <br> with newlines and return plain text', () => {
        const template = Handlebars.compile('{{{strReplace "First Line<br>Second Line" html=1}}}');
        const result = template({});
        expect(result).toBe('First Line&#10;Second Line');
    });

    // Тест для останньої заміни символу
    it('should replace the last occurrence of a character', () => {
        const template = Handlebars.compile('{{strReplace "one two one" "one" "ONE" last=1}}');
        const result = template({});
        expect(result).toBe('one two ONE');
    });

    // Тест для некоректних параметрів заміни
    it('should return error message for invalid replacement parameters', () => {
        const template = Handlebars.compile('{{strReplace "text" 123 456}}');
        const result = template({});
        expect(result).toBe('Invalid replacement parameters');
    });

    // Тест для випадку, коли немає рядка для заміни
    it('should return an empty string when no string is provided', () => {
        const template = Handlebars.compile('{{strReplace "" " " "_"}}');
        const result = template({});
        expect(result).toBe('');
    });
});
